//! The operations as typed arguments. Each struct is one tool: its doc comment is the tool's
//! description and its fields, with their doc comments, are the JSON Schema of its input,
//! generated by `schemars` ([`tools`]), so Anthropic tools, OpenAI functions and MCP tools
//! come from one definition. Cells are world cells `[x, y, z]`: x right, y up, z toward the
//! viewer.

use schemars::JsonSchema;
use schemars::generate::SchemaSettings;
use serde::{Deserialize, Serialize};
use serde_json::Value;

/// A world cell `[x, y, z]`.
pub type Cell = [i32; 3];

/// The largest coordinate a call may give, either way.
pub const MAX_COORD: i64 = 1 << 24;

/// add sets every cell to the slot, erase clears it, paint recolours only cells that hold a voxel.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Deserialize, Serialize, JsonSchema)]
#[serde(rename_all = "lowercase")]
pub enum Mode {
    #[default]
    Add,
    Erase,
    Paint,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Deserialize, Serialize, JsonSchema)]
#[serde(rename_all = "lowercase")]
pub enum Axis {
    X,
    Y,
    Z,
}

impl Axis {
    pub fn index(self) -> usize {
        match self {
            Axis::X => 0,
            Axis::Y => 1,
            Axis::Z => 2,
        }
    }
}

/// A side of a voxel: top is +y, bottom -y, right +x, left -x, front +z (toward the viewer)
/// and back -z.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Deserialize, Serialize, JsonSchema)]
#[serde(rename_all = "lowercase")]
pub enum Side {
    Top,
    Bottom,
    Left,
    Right,
    Front,
    Back,
}

impl Side {
    pub fn name(self) -> &'static str {
        match self {
            Side::Top => "top",
            Side::Bottom => "bottom",
            Side::Left => "left",
            Side::Right => "right",
            Side::Front => "front",
            Side::Back => "back",
        }
    }

    /// The unit normal out of this side.
    pub fn normal(self) -> Cell {
        match self {
            Side::Top => [0, 1, 0],
            Side::Bottom => [0, -1, 0],
            Side::Right => [1, 0, 0],
            Side::Left => [-1, 0, 0],
            Side::Front => [0, 0, 1],
            Side::Back => [0, 0, -1],
        }
    }
}

/// How a selection combines with the current one.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Deserialize, Serialize, JsonSchema)]
#[serde(rename_all = "lowercase")]
pub enum SelectMode {
    #[default]
    Replace,
    Add,
    Subtract,
}

/// The scene as text: editable bounds, voxel count, used palette slots with colour, count and bounds, a top-down height map, the parts, the selection, what is staged so far, and object and layer names and palette notes from the file.
#[derive(Clone, Debug, Default, Deserialize, Serialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct SceneSummary {}

/// Read exact cells. cells gives each listed cell's slot (0 is empty); columns gives the top voxel of each [x, z] column (its y and slot, or null when the column is empty), the cheap way to find the surface to build on; from and to list every filled cell in that box. At most 4096 cells or columns per call.
#[derive(Clone, Debug, Default, Deserialize, Serialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct GetVoxels {
    /// Cells [x, y, z] to read.
    #[serde(default)]
    pub cells: Vec<Cell>,
    /// Columns [x, z] whose top voxel to read.
    #[serde(default)]
    pub columns: Vec<[i32; 2]>,
    /// Corner of a box whose filled cells to list.
    pub from: Option<Cell>,
    /// Opposite corner of that box.
    pub to: Option<Cell>,
}

/// One layer of the scene as text rows, one character per cell ('.' is empty), with a legend from character to palette slot. axis y is a top-down layer at height index (rows from back, low z, to front, high z; columns from low x to high x); axis x and z are upright layers (rows from top to bottom; columns along z or x, low to high). from and to limit it to a box; at most 128 x 128 cells.
#[derive(Clone, Debug, Deserialize, Serialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct Slice {
    pub axis: Axis,
    /// The layer's coordinate along the axis.
    pub index: i32,
    /// Corner of the box to show (its coordinate along the axis is ignored).
    pub from: Option<Cell>,
    /// Opposite corner.
    pub to: Option<Cell>,
}

/// Find parts of the scene by name. Parts are connected voxels of one colour as the scene was opened, named by colour and shape ("dark green blob", "brown column") with the part each rests on, and the parts your earlier edits named. query matches words of a part's name or its id (p12); without it every part is listed, biggest first. Any edit that takes part works on that part's voxels.
#[derive(Clone, Debug, Default, Deserialize, Serialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct FindParts {
    /// Words to look for, or a part id.
    pub query: Option<String>,
}

/// Set listed cells to a palette slot (at most 4096 cells).
#[derive(Clone, Debug, Deserialize, Serialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct Place {
    /// Cells [x, y, z].
    pub cells: Vec<Cell>,
    #[schemars(range(min = 1, max = 255))]
    pub slot: u8,
    /// Name the voxels this makes as a part, to find it later ("flag").
    pub name: Option<String>,
}

/// Clear listed cells (at most 4096), or every voxel of one or more parts. For a region use box with mode erase.
#[derive(Clone, Debug, Default, Deserialize, Serialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct Erase {
    /// Cells [x, y, z].
    #[serde(default)]
    pub cells: Vec<Cell>,
    /// A part id or name from the summary or find_parts.
    pub part: Option<String>,
    /// Several part ids or names.
    #[serde(default)]
    pub parts: Vec<String>,
}

/// Fill the box between two corner cells (both included). hollow keeps only its outer shell.
#[derive(Clone, Debug, Deserialize, Serialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct BoxShape {
    pub from: Cell,
    pub to: Cell,
    /// Needed unless mode is erase.
    #[schemars(range(min = 1, max = 255))]
    pub slot: Option<u8>,
    #[serde(default)]
    pub mode: Mode,
    #[serde(default)]
    pub hollow: bool,
    /// Name the voxels this makes as a part.
    pub name: Option<String>,
}

/// A straight line of cells between two cells, both included.
#[derive(Clone, Debug, Deserialize, Serialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct Line {
    pub from: Cell,
    pub to: Cell,
    /// Needed unless mode is erase.
    #[schemars(range(min = 1, max = 255))]
    pub slot: Option<u8>,
    #[serde(default)]
    pub mode: Mode,
    /// Name the voxels this makes as a part.
    pub name: Option<String>,
}

/// A ball of radius 1 to 64 around a cell. flat_axis makes a disc across that axis instead (flat_axis y: a horizontal disc).
#[derive(Clone, Debug, Deserialize, Serialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct Sphere {
    pub center: Cell,
    #[schemars(range(min = 1, max = 64))]
    pub radius: i32,
    /// Needed unless mode is erase.
    #[schemars(range(min = 1, max = 255))]
    pub slot: Option<u8>,
    #[serde(default)]
    pub mode: Mode,
    pub flat_axis: Option<Axis>,
    /// Name the voxels this makes as a part.
    pub name: Option<String>,
}

/// A disc of radius 1 to 64 around a cell, flat across axis (default y: a horizontal disc), as the center brush's circle draws it.
#[derive(Clone, Debug, Deserialize, Serialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct Circle {
    pub center: Cell,
    #[schemars(range(min = 1, max = 64))]
    pub radius: i32,
    /// Needed unless mode is erase.
    #[schemars(range(min = 1, max = 255))]
    pub slot: Option<u8>,
    #[serde(default)]
    pub mode: Mode,
    /// The axis the disc is flat across (default y).
    pub axis: Option<Axis>,
    /// Name the voxels this makes as a part.
    pub name: Option<String>,
}

/// Work on one face, as the face brush does: the voxels of cell's colour connected to it in its layer whose side is open (up to 120,000). add puts a layer of slot on that side of them, erase clears them and paint recolours them.
#[derive(Clone, Debug, Deserialize, Serialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct FaceShape {
    /// A voxel of the face.
    pub cell: Cell,
    /// Which side of it (default top).
    pub side: Option<Side>,
    /// Needed unless mode is erase.
    #[schemars(range(min = 1, max = 255))]
    pub slot: Option<u8>,
    #[serde(default)]
    pub mode: Mode,
    /// Name the voxels this makes as a part.
    pub name: Option<String>,
}

/// Recolour every selected voxel with a slot.
#[derive(Clone, Debug, Deserialize, Serialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct Fill {
    #[schemars(range(min = 1, max = 255))]
    pub slot: u8,
}

/// Recolour filled cells: those of one or more parts, of slot from_slot, the selection, or those in a box (from, to). Empty cells stay empty.
#[derive(Clone, Debug, Deserialize, Serialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct Paint {
    /// The new slot.
    #[schemars(range(min = 1, max = 255))]
    pub slot: u8,
    /// A part id or name.
    pub part: Option<String>,
    /// Several part ids or names.
    #[serde(default)]
    pub parts: Vec<String>,
    /// Recolour every voxel of this slot.
    #[schemars(range(min = 1, max = 255))]
    pub from_slot: Option<u8>,
    /// Recolour the selection.
    #[serde(default)]
    pub selection: bool,
    pub from: Option<Cell>,
    pub to: Option<Cell>,
}

/// Select filled cells: in a box (from, to), of a palette slot (color), of one or more parts, the face of a voxel (face, with side: the connected voxels of its colour in its layer whose side is open, as a select click with Face does), the volume of a voxel (volume: every voxel connected to it through faces, whatever its colour), all, none, or invert (every voxel not selected, and none of those that are). The selection is the assistant's own; fill paints it.
#[derive(Clone, Debug, Default, Deserialize, Serialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct Select {
    pub from: Option<Cell>,
    pub to: Option<Cell>,
    #[schemars(range(min = 1, max = 255))]
    pub color: Option<u8>,
    /// A part id or name.
    pub part: Option<String>,
    /// Several part ids or names.
    #[serde(default)]
    pub parts: Vec<String>,
    /// A voxel whose face to select.
    pub face: Option<Cell>,
    /// The side of face's voxel (default top).
    pub side: Option<Side>,
    /// A voxel whose connected volume to select.
    pub volume: Option<Cell>,
    #[serde(default)]
    pub all: bool,
    #[serde(default)]
    pub none: bool,
    /// Select every voxel that is not selected and drop those that are (with nothing selected, every voxel); mode is not used.
    #[serde(default)]
    pub invert: bool,
    #[serde(default)]
    pub mode: SelectMode,
}

/// What transform does.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Deserialize, Serialize, JsonSchema)]
#[serde(rename_all = "lowercase")]
pub enum TransformKind {
    Move,
    Rotate,
    Flip,
    Loop,
}

/// Move, turn, mirror or wrap the selection, or every voxel when nothing is selected, as the select flyout does. move shifts by offset [dx, dy, dz]; rotate turns 90 degrees about axis (counter-clockwise looking down it) around the middle of what moves; flip mirrors across that middle on axis; loop shifts by steps cells along axis and wraps what leaves the moved voxels' box round to its other side. The selection moves with the voxels. If any voxel would land outside the editable bounds nothing moves and the call fails: resize first.
#[derive(Clone, Debug, Deserialize, Serialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct Transform {
    pub kind: TransformKind,
    /// [dx, dy, dz], for move.
    pub offset: Option<Cell>,
    /// For rotate, flip and loop.
    pub axis: Option<Axis>,
    /// Cells to loop by, for loop (default 1; negative goes the other way).
    pub steps: Option<i32>,
}

/// Copy the selected voxels to your clipboard (not the user's), for paste.
#[derive(Clone, Debug, Default, Deserialize, Serialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct CopySelection {}

/// Copy the selected voxels to your clipboard, then erase them.
#[derive(Clone, Debug, Default, Deserialize, Serialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct Cut {}

/// Paste your clipboard with the bottom centre of its box on cell at, or without at beside where it was copied from (on +x). Cells outside the editable bounds are skipped with a warning. The pasted voxels become the selection.
#[derive(Clone, Debug, Default, Deserialize, Serialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct Paste {
    pub at: Option<Cell>,
}

/// Erase the selected voxels; the selection empties.
#[derive(Clone, Debug, Default, Deserialize, Serialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct Delete {}

/// Keep only the voxels that can be seen from outside, a shell one voxel thick: of the selection, or of every voxel when nothing is selected.
#[derive(Clone, Debug, Default, Deserialize, Serialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct Hollow {}

/// Fill the empty space the selection (or every voxel, when nothing is selected) encloses with a slot. Space open to the outside, like the inside of a cup, is not filled.
#[derive(Clone, Debug, Deserialize, Serialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct FillInside {
    #[schemars(range(min = 1, max = 255))]
    pub slot: u8,
}

/// Resize the editable bounds to size [x, y, z] (1 to 2048 each), keeping the bottom and the middle on x and z, as the Bounds panel does. Grow them before building beyond them. Voxels outside the new bounds are erased, and the result says how many.
#[derive(Clone, Debug, Deserialize, Serialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct Resize {
    pub size: [u32; 3],
}

/// Fit the editable bounds to the voxels exactly.
#[derive(Clone, Debug, Default, Deserialize, Serialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct Crop {}

/// A palette slot's material type.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Deserialize, Serialize, JsonSchema)]
#[serde(rename_all = "lowercase")]
pub enum MaterialKind {
    Diffuse,
    Metal,
    Plastic,
    Glass,
    Emit,
}

/// Set a palette slot's material, as the Material tab does: its type and its sliders. Every voxel of that slot changes. A slider not given keeps its value. Each type reads its own: metal roughness and metalness, plastic roughness and specular, glass roughness, transparency, refraction and attenuation, emit emission and power.
#[derive(Clone, Debug, Deserialize, Serialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct MaterialSet {
    #[schemars(range(min = 1, max = 255))]
    pub slot: u8,
    #[serde(rename = "type")]
    pub kind: Option<MaterialKind>,
    #[schemars(range(min = 0, max = 1))]
    pub roughness: Option<f32>,
    #[schemars(range(min = 0, max = 1))]
    pub metalness: Option<f32>,
    #[schemars(range(min = 0, max = 1))]
    pub specular: Option<f32>,
    #[schemars(range(min = 0, max = 1))]
    pub transparency: Option<f32>,
    /// Refractive index.
    #[schemars(range(min = 1, max = 3))]
    pub refraction: Option<f32>,
    #[schemars(range(min = 0, max = 1))]
    pub attenuation: Option<f32>,
    #[schemars(range(min = 0, max = 1))]
    pub emission: Option<f32>,
    #[schemars(range(min = 0, max = 4))]
    pub power: Option<f32>,
}

/// Make voxels an object of their own, as the select flyout's To new object does: those of one or more parts, of slot from_slot, the selection, or those in a box (from, to). They leave this object's model and become a new object right after it, under the same group and on the same layer, each voxel on the world cell it was on, so nothing moves in the world. Not every voxel: what is left stays in this object, which rename names. Not on a linked copy, whose model other objects share. In a new scene the scene first becomes a world of one object. The new object is staged like every edit and made when the user applies the change; the result gives its node, for rename, and its voxels read as gone from this model.
#[derive(Clone, Debug, Default, Deserialize, Serialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct MakeObject {
    /// A part id or name.
    pub part: Option<String>,
    /// Several part ids or names.
    #[serde(default)]
    pub parts: Vec<String>,
    /// Every voxel of this slot.
    #[schemars(range(min = 1, max = 255))]
    pub from_slot: Option<u8>,
    /// The selected voxels.
    #[serde(default)]
    pub selection: bool,
    pub from: Option<Cell>,
    pub to: Option<Cell>,
    /// What the object is ("mug"), at most 64 characters (default "object N").
    pub name: Option<String>,
}

/// Move an object or group of the world by offset [dx, dy, dz] cells, as a drag in world mode does. node is its number from the summary's world list. A group moves with everything in it.
#[derive(Clone, Debug, Deserialize, Serialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct MoveObject {
    pub node: usize,
    pub offset: Cell,
}

/// Copy an object or group of the world and put the copy beside it on +x, as Cmd-D does. linked makes a linked copy that shares the models (editing one changes every copy, as Cmd-Shift-D does); otherwise each copied object gets its own model. The result gives the copy's node.
#[derive(Clone, Debug, Deserialize, Serialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct Duplicate {
    pub node: usize,
    #[serde(default)]
    pub linked: bool,
}

/// Put objects or groups of the world that share a parent into a new group, where the first of them was, as Cmd-G does. The result gives the group's node.
#[derive(Clone, Debug, Deserialize, Serialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct Group {
    pub nodes: Vec<usize>,
}

/// Take a group of the world apart, as Cmd-Shift-G does: what it holds moves up into its parent, where it was, keeping where it is in the world (and hidden if the group was).
#[derive(Clone, Debug, Deserialize, Serialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct Ungroup {
    pub node: usize,
}

/// Hide an object or group of the world, or show it again with hidden false, as its eye in the scene tree does. A hidden object stays in the file.
#[derive(Clone, Debug, Deserialize, Serialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct Hide {
    pub node: usize,
    #[serde(default = "yes")]
    pub hidden: bool,
}

fn yes() -> bool {
    true
}

/// Put an object or group of the world (and everything in it) on a layer: layer is an id from the summary's layers, or new_layer names a new layer to make for it. An object on a hidden layer does not show.
#[derive(Clone, Debug, Deserialize, Serialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct SetLayer {
    pub node: usize,
    pub layer: Option<i32>,
    /// The name of a new layer, instead of layer.
    pub new_layer: Option<String>,
}

/// Delete an object or group of the world (and everything in it), as Backspace in world mode does. Its models stay in the file only while undo can bring it back.
#[derive(Clone, Debug, Deserialize, Serialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct DeleteObject {
    pub node: usize,
}

/// Rename an object or group of the world (node) or a layer (layer, an id from the summary's layers), as a double-click in the scene tree or the layer list does. An empty name clears it. While one object's model shows, node may be any object of the world (this one, or one make_object staged).
#[derive(Clone, Debug, Deserialize, Serialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct Rename {
    pub node: Option<usize>,
    pub layer: Option<i32>,
    /// At most 64 characters.
    pub name: String,
}

/// Add a layer to the world, as the layer list's + does. The result gives its id, for set_layer.
#[derive(Clone, Debug, Default, Deserialize, Serialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct NewLayer {
    /// 1 to 64 characters (default "layer N", as the + names it).
    pub name: Option<String>,
}

/// Hide a layer of the world (layer is an id from the summary's layers), or show it again with hidden false, as its eye in the layer list does. Objects on a hidden layer do not show.
#[derive(Clone, Debug, Deserialize, Serialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct HideLayer {
    pub layer: i32,
    #[serde(default = "yes")]
    pub hidden: bool,
}

/// Set a palette slot's colour as #rrggbb. Every voxel of that slot changes colour. Pick an unused slot for a new colour.
#[derive(Clone, Debug, Deserialize, Serialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct PaletteSet {
    #[schemars(range(min = 1, max = 255))]
    pub slot: u8,
    /// The colour, #rrggbb.
    pub hex: String,
}

/// Swap two palette slots, as Swap with… does: their colours and materials trade places and the voxels of each take the other slot, so the model looks the same and only the palette order changes.
#[derive(Clone, Debug, Deserialize, Serialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct PaletteSwap {
    #[schemars(range(min = 1, max = 255))]
    pub a: u8,
    #[schemars(range(min = 1, max = 255))]
    pub b: u8,
}

/// Give slot to the colour and material of slot from, as Copy to… does. Every voxel of slot to changes.
#[derive(Clone, Debug, Deserialize, Serialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct PaletteCopy {
    #[schemars(range(min = 1, max = 255))]
    pub from: u8,
    #[schemars(range(min = 1, max = 255))]
    pub to: u8,
}

/// Where look looks from.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Deserialize, Serialize, JsonSchema)]
#[serde(rename_all = "lowercase")]
pub enum LookView {
    /// From +z, toward -z.
    Front,
    /// From -z.
    Back,
    /// From -x.
    Left,
    /// From +x.
    Right,
    /// From above, -z at the top of the picture.
    Top,
    /// From below.
    Bottom,
    /// From the front-right-top corner.
    #[default]
    Iso,
    /// The user's own view in the vxr window, as they see it (live mode only).
    Current,
}

/// See the scene: a PNG picture of the voxels as the editor view draws them (palette colours, the sun from the front-right-top with shadows, the ground under the model, the selection tinted orange), and what it shows as text. Every view but current is orthographic and frames all the voxels; front, back, left, right, top and bottom look straight along an axis, so a voxel is a square and the text gives which cells the picture spans. Look after building to check the result.
#[derive(Clone, Debug, Default, Deserialize, Serialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct Look {
    #[serde(default)]
    pub view: LookView,
    /// The picture's longer side in pixels, 64 to 1024 (default 512).
    #[schemars(range(min = 64, max = 1024))]
    pub size: Option<u32>,
}

/// Take back your own last edit (never the user's).
#[derive(Clone, Debug, Default, Deserialize, Serialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct Undo {}

/// Bring back your own edit that undo took back last, as long as you made no edit since.
#[derive(Clone, Debug, Default, Deserialize, Serialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct Redo {}

/// Finish: the change goes to the user for review. Give a one-line summary of what you changed.
#[derive(Clone, Debug, Deserialize, Serialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct Done {
    pub summary: String,
}

/// One tool as a provider takes it: a name, a description and the JSON Schema of its input.
#[derive(Clone, Debug, Serialize)]
pub struct Tool {
    pub name: &'static str,
    pub description: String,
    pub parameters: Value,
}

macro_rules! ops {
    ($($name:literal => $variant:ident($args:ty),)*) => {
        /// One call, parsed.
        #[derive(Clone, Debug)]
        pub enum Op {
            $($variant($args),)*
        }

        impl Op {
            /// Parse a call by its tool name. Whole floats count as integers and a missing
            /// input as `{}`, as models send them. Numbers beyond [`MAX_COORD`] are refused.
            pub fn parse(name: &str, mut args: Value) -> Result<Op, String> {
                integers(&mut args);
                in_range(&args)?;
                if args.is_null() {
                    args = Value::Object(Default::default());
                }
                match name {
                    $($name => serde_json::from_value(args).map(Op::$variant).map_err(|e| e.to_string()),)*
                    _ => Err(format!("unknown tool {name}")),
                }
            }

            pub fn name(&self) -> &'static str {
                match self {
                    $(Op::$variant(_) => $name,)*
                }
            }
        }

        /// Every tool, in the order they are offered.
        pub fn tools() -> Vec<Tool> {
            vec![$(tool::<$args>($name),)*]
        }
    };
}

