/// What a call does, see [`Op::kind`].
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum OpKind {
    /// Only reads the scene.
    Query,
    /// Changes the selection or the clipboard, not the scene: no undo step, nothing to save.
    Selection,
    /// Changes the scene: one undo step, and the file has unsaved edits.
    Edit,
    /// `undo`, `redo` and `done`: they act on the session's steps, not on the scene's cells.
    Control,
}

impl Op {
    /// What the call does to the session, the one place that says which calls are edits.
    pub fn kind(&self) -> OpKind {
        match self {
            Op::SceneSummary(_) | Op::GetVoxels(_) | Op::Slice(_) | Op::FindParts(_) | Op::Look(_) => OpKind::Query,
            Op::Select(_) | Op::Copy(_) => OpKind::Selection,
            Op::Undo(_) | Op::Redo(_) | Op::Done(_) => OpKind::Control,
            _ => OpKind::Edit,
        }
    }

    /// Whether the call only reads the scene.
    pub fn is_query(&self) -> bool {
        self.kind() == OpKind::Query
    }

    /// Whether the call answers with a picture ([`crate::Session::take_image`]) besides its
    /// text, which only a caller that passes pictures on to the model offers.
    pub fn has_image(name: &str) -> bool {
        name == "look"
    }
}

/// Round whole floats to integers, so `3.0` reads as `3`.
fn integers(v: &mut Value) {
    match v {
        Value::Number(n) if !n.is_i64() && !n.is_u64() => {
            if let Some(f) = n.as_f64().filter(|f| f.is_finite() && f.fract() == 0.0 && f.abs() < 1e15) {
                *v = Value::from(f as i64);
            }
        }
        Value::Array(a) => a.iter_mut().for_each(integers),
        Value::Object(o) => o.values_mut().for_each(integers),
        _ => {}
    }
}

fn in_range(v: &Value) -> Result<(), String> {
    match v {
        Value::Number(n) if n.as_f64().is_some_and(|f| f.abs() > MAX_COORD as f64) => {
            Err(format!("{n} is out of range: coordinates are within -{MAX_COORD}..{MAX_COORD}"))
        }
        Value::Array(a) => a.iter().try_for_each(in_range),
        Value::Object(o) => o.values().try_for_each(in_range),
        _ => Ok(()),
    }
}

fn tool<T: JsonSchema>(name: &'static str) -> Tool {
    let generator = SchemaSettings::draft2020_12()
        .with(|s| {
            s.inline_subschemas = true;
        })
        .into_generator();
    let mut v = generator.into_root_schema_for::<T>().to_value();
    let description = v
        .as_object_mut()
        .and_then(|o| o.remove("description"))
        .and_then(|d| d.as_str().map(str::to_string))
        .unwrap_or_default();
    tidy(&mut v);
    let o = v.as_object_mut().expect("a schema object");
    o.remove("title");
    o.remove("$schema");
    o.entry("properties").or_insert_with(|| Value::Object(Default::default()));
    o.insert("additionalProperties".into(), Value::Bool(false));
    Tool { name, description, parameters: v }
}

/// Keep a schema to what every provider reads: no `format` (schemars writes `int32` and
/// `uint8`), no titles, and an optional field as its plain type rather than "or null".
fn tidy(v: &mut Value) {
    match v {
        Value::Object(o) => {
            o.remove("format");
            o.remove("title");
            if let Some(Value::Array(types)) = o.get("type") {
                let kept: Vec<Value> = types.iter().filter(|t| t.as_str() != Some("null")).cloned().collect();
                if kept.len() == 1 {
                    o.insert("type".into(), kept[0].clone());
                }
            }
            if let Some(Value::Array(any)) = o.get("anyOf") {
                let kept: Vec<Value> =
                    any.iter().filter(|s| s.get("type").and_then(Value::as_str) != Some("null")).cloned().collect();
                if kept.len() == 1 {
                    o.remove("anyOf");
                    if let Value::Object(inner) = &kept[0] {
                        for (k, x) in inner {
                            o.entry(k.clone()).or_insert_with(|| x.clone());
                        }
                    }
                }
            }
            if let Some(Value::Array(values)) = o.get_mut("enum") {
                values.retain(|v| !v.is_null());
            }
            if o.get("default").is_some_and(Value::is_null) {
                o.remove("default");
            }
            o.values_mut().for_each(tidy);
        }
        Value::Array(a) => a.iter_mut().for_each(tidy),
        _ => {}
    }
}
